if(EditorApplication.isPlaying)throw new System.Exception("Edit required");var all=UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var temporary=new System.Collections.Generic.List<GameObject>();var results=new System.Collections.Generic.List<object>();
Transform Find(string n)=>all.First(t=>t.name==n&&(t.parent==null||t.parent.name!=n));
MeshCollider Support(Transform t){var mf=t.GetComponentsInChildren<MeshFilter>().First(m=>m.GetComponent<Renderer>().enabled);var g=new GameObject("Temporary furniture support probe");temporary.Add(g);g.transform.SetPositionAndRotation(mf.transform.position,mf.transform.rotation);g.transform.localScale=mf.transform.lossyScale;var c=g.AddComponent<MeshCollider>();c.sharedMesh=mf.sharedMesh;return c;}
void Sample(string name,Vector3 point,MeshCollider support){bool hit=support.Raycast(new Ray(point+Vector3.up*.05f,Vector3.down),out var h,.09f);float gap=hit?h.distance-.05f:999;results.Add(new{item=name,point=point.ToString("F4"),support=support.sharedMesh.name,gap,passed=hit&&gap>=-.006f&&gap<.012f});}
try{var bench=Support(Find("CM_AF01_PreparationBench"));var story=Find("CM_LI03_WorkSurfaceStory");foreach(float x in new[]{-.15f,.15f})Sample("Working linen contact",story.TransformPoint(new Vector3(x,.003f,0)),bench);Sample("Notebook",Find("CM_LI03_FieldNotebook").position,bench);
var counter=Support(Find("CM_HR02_CounterCraft"));Sample("Counter jar",Find("CM_HR02_CounterJar").position,counter);Sample("Record cluster ink foot",Find("CM_HR02_RecordsCluster").TransformPoint(new Vector3(.12f,0,-.05f)),counter);
// Hanging-loop contacts use separate documented fixture measurements.
}finally{foreach(var g in temporary)UnityEngine.Object.DestroyImmediate(g);}System.IO.File.WriteAllText("ArtSource/Blender/Interiors/CrookedMortar/LivedIn03/SurfaceValidation.json",Newtonsoft.Json.JsonConvert.SerializeObject(results,Newtonsoft.Json.Formatting.Indented));return results;
